-- MySQL 8.0+ schema. Run before database/seed.sql.
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status ENUM('active','inactive','suspended') NOT NULL DEFAULT 'active', last_login_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_users_role FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE student_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, student_number VARCHAR(50) NOT NULL UNIQUE, class_name VARCHAR(80) NULL, CONSTRAINT fk_student_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE extracurricular_groups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT NULL, sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0);
CREATE TABLE extracurriculars (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, short_description VARCHAR(280) NOT NULL, description TEXT NOT NULL, status ENUM('active','inactive','archived') NOT NULL DEFAULT 'active', is_featured BOOLEAN NOT NULL DEFAULT FALSE, settings JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_extra_group FOREIGN KEY(group_id) REFERENCES extracurricular_groups(id), INDEX idx_extra_public (status,is_featured,name));
CREATE TABLE positions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, grants_management BOOLEAN NOT NULL DEFAULT FALSE, grants_finance BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, extracurricular_id BIGINT UNSIGNED NOT NULL, position_id BIGINT UNSIGNED NOT NULL, status ENUM('active','inactive','completed') NOT NULL DEFAULT 'active', joined_at DATE NOT NULL, ended_at DATE NULL, UNIQUE KEY uq_membership_scope(user_id,extracurricular_id), INDEX idx_membership_extra(extracurricular_id,status), CONSTRAINT fk_membership_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_membership_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_membership_position FOREIGN KEY(position_id) REFERENCES positions(id));
CREATE TABLE staff_extracurriculars (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, extracurricular_id BIGINT UNSIGNED NOT NULL, assignment_type ENUM('pembina','pelatih') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_staff_scope(user_id,extracurricular_id,assignment_type), CONSTRAINT fk_staff_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_staff_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id));
CREATE TABLE activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, created_by BIGINT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, activity_date DATE NOT NULL, start_time TIME NULL, end_time TIME NULL, location VARCHAR(200) NULL, material TEXT NULL, instructor VARCHAR(150) NULL, custom_fields JSON NULL, visibility ENUM('internal','public') NOT NULL DEFAULT 'internal', status ENUM('planned','completed','cancelled') NOT NULL DEFAULT 'planned', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_activity_extra_date(extracurricular_id,activity_date), CONSTRAINT fk_activity_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_activity_creator FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE activity_participants (activity_id BIGINT UNSIGNED NOT NULL, membership_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(activity_id,membership_id), CONSTRAINT fk_participant_activity FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE, CONSTRAINT fk_participant_membership FOREIGN KEY(membership_id) REFERENCES memberships(id));
CREATE TABLE attendance_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, activity_id BIGINT UNSIGNED NOT NULL, opened_by BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL, opens_at DATETIME NOT NULL, closes_at DATETIME NOT NULL, status ENUM('open','closed') NOT NULL DEFAULT 'open', closed_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_attendance_token(status,token_hash), CONSTRAINT fk_session_activity FOREIGN KEY(activity_id) REFERENCES activities(id), CONSTRAINT fk_session_opener FOREIGN KEY(opened_by) REFERENCES users(id), CONSTRAINT fk_session_closer FOREIGN KEY(closed_by) REFERENCES users(id));
CREATE TABLE attendance_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attendance_session_id BIGINT UNSIGNED NOT NULL, membership_id BIGINT UNSIGNED NOT NULL, checked_in_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('present','late','excused','absent') NOT NULL DEFAULT 'present', corrected_by BIGINT UNSIGNED NULL, correction_note VARCHAR(500) NULL, UNIQUE KEY uq_attendance_checkin(attendance_session_id,membership_id), CONSTRAINT fk_record_session FOREIGN KEY(attendance_session_id) REFERENCES attendance_sessions(id), CONSTRAINT fk_record_membership FOREIGN KEY(membership_id) REFERENCES memberships(id), CONSTRAINT fk_record_corrector FOREIGN KEY(corrected_by) REFERENCES users(id));
CREATE TABLE journals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, activity_id BIGINT UNSIGNED NOT NULL UNIQUE, extracurricular_id BIGINT UNSIGNED NOT NULL, authored_by BIGINT UNSIGNED NOT NULL, fields JSON NOT NULL, published_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_journal_activity FOREIGN KEY(activity_id) REFERENCES activities(id), CONSTRAINT fk_journal_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_journal_author FOREIGN KEY(authored_by) REFERENCES users(id));
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uploaded_by BIGINT UNSIGNED NOT NULL, disk_path VARCHAR(255) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, byte_size BIGINT UNSIGNED NOT NULL, visibility ENUM('private','public') NOT NULL DEFAULT 'private', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_document_uploader FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE proposals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, submitted_by BIGINT UNSIGNED NOT NULL, title VARCHAR(250) NOT NULL, status ENUM('draft','submitted','revision_requested','rejected_by_wakasek','forwarded','approved','rejected_by_principal') NOT NULL DEFAULT 'draft', current_version_number INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, INDEX idx_proposal_status(status), CONSTRAINT fk_proposal_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_proposal_submitter FOREIGN KEY(submitted_by) REFERENCES users(id));
CREATE TABLE proposal_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id BIGINT UNSIGNED NOT NULL, version_number INT UNSIGNED NOT NULL, document_id BIGINT UNSIGNED NOT NULL, submitted_by BIGINT UNSIGNED NOT NULL, note TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_proposal_version(proposal_id,version_number), CONSTRAINT fk_version_proposal FOREIGN KEY(proposal_id) REFERENCES proposals(id), CONSTRAINT fk_version_document FOREIGN KEY(document_id) REFERENCES documents(id), CONSTRAINT fk_version_submitter FOREIGN KEY(submitted_by) REFERENCES users(id));
CREATE TABLE proposal_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_version_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, reviewer_stage ENUM('wakasek','kepala_sekolah') NOT NULL, decision ENUM('revision_requested','rejected','forwarded','approved') NOT NULL, notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_review_version FOREIGN KEY(proposal_version_id) REFERENCES proposal_versions(id), CONSTRAINT fk_review_user FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE proposal_annotations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_version_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, page_number INT UNSIGNED NOT NULL, annotation JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_annotation_version FOREIGN KEY(proposal_version_id) REFERENCES proposal_versions(id), CONSTRAINT fk_annotation_user FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE financial_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, recorded_by BIGINT UNSIGNED NOT NULL, transaction_date DATE NOT NULL, type ENUM('income','expense') NOT NULL, amount DECIMAL(15,2) NOT NULL, description VARCHAR(500) NOT NULL, receipt_document_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_finance_scope(extracurricular_id,transaction_date), CONSTRAINT fk_finance_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_finance_user FOREIGN KEY(recorded_by) REFERENCES users(id), CONSTRAINT fk_finance_doc FOREIGN KEY(receipt_document_id) REFERENCES documents(id));
CREATE TABLE achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, event_name VARCHAR(250) NOT NULL, event_date DATE NULL, level_name VARCHAR(100) NULL, result_text VARCHAR(250) NOT NULL, participant_summary TEXT NULL, documentation_document_id BIGINT UNSIGNED NULL, is_public BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_achievement_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_achievement_document FOREIGN KEY(documentation_document_id) REFERENCES documents(id));
CREATE TABLE news (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NULL, author_id BIGINT UNSIGNED NULL, title VARCHAR(250) NOT NULL, slug VARCHAR(260) NOT NULL UNIQUE, excerpt VARCHAR(500) NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', published_at DATETIME NULL, INDEX idx_news_public(status,published_at), CONSTRAINT fk_news_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_news_author FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE score_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_key VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, points DECIMAL(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, approval_note TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_rule_creator FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, actor_user_id BIGINT UNSIGNED NULL, event_key VARCHAR(80) NOT NULL, source_type VARCHAR(80) NOT NULL, source_id BIGINT UNSIGNED NOT NULL, metadata JSON NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_activitylog_scope(extracurricular_id,event_key,occurred_at), CONSTRAINT fk_activitylog_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_activitylog_actor FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE extracurricular_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id BIGINT UNSIGNED NOT NULL, activity_log_id BIGINT UNSIGNED NOT NULL UNIQUE, score_rule_id BIGINT UNSIGNED NOT NULL, points DECIMAL(10,2) NOT NULL, awarded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_score_extra FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), CONSTRAINT fk_score_log FOREIGN KEY(activity_log_id) REFERENCES activity_logs(id), CONSTRAINT fk_score_rule FOREIGN KEY(score_rule_id) REFERENCES score_rules(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, metadata JSON NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_entity(entity_type,entity_id,created_at), CONSTRAINT fk_audit_actor FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL);
